-- Throwaway roles and schema for the Core rollback proof. Passwords come from psql variables
-- (owner_pw, runtime_pw) generated by run.sh at runtime. Nothing here is a real credential.
\set ON_ERROR_STOP on

-- Migration role: owns database and schema identity. Flyway DDL and the runtime GRANT reconcile run as this role.
CREATE ROLE identity_owner LOGIN PASSWORD :'owner_pw';
-- Runtime role: no ownership, no DDL. Core's runtime datasource uses this role.
CREATE ROLE identity_runtime LOGIN PASSWORD :'runtime_pw';

CREATE DATABASE app OWNER identity_owner;
\c app
REVOKE CONNECT ON DATABASE app FROM PUBLIC;
GRANT CONNECT ON DATABASE app TO identity_owner, identity_runtime;

-- Core creates no schema (createSchemas=false in IdentityPersistenceConfiguration); the owner provisions it.
CREATE SCHEMA identity AUTHORIZATION identity_owner;

-- Assumption: Core's JPA mappings are unqualified and Core sets no default_schema (checked in code).
-- The DEV role search_path is not read; this is the test assumption, to be verified in DEV.
ALTER ROLE identity_owner SET search_path = identity;
ALTER ROLE identity_runtime SET search_path = identity;
